from content_lib import concept, card

TH = 'thesis'
N = 'nie2023patchtst'

# ---------------- WTH ----------------
concept('C-wth-result', 'F', 'Result 1: WTH (Informer wins)',
 'After 10 epochs and with PatchTST included, Informer has the best MAE, MSE and RMSE of the three Transformers on WTH and is also the fastest to train. PatchTST wins only on MAPE, which is not tabulated. This is the first sign that PatchTST\'s advantage is dataset-conditional.',
 ['4.4.1'], ('4.4.1', 'Informer achieves the best MAE, MSE, and RMSE of the three Transformers on WTH'), [TH], 0.5)
card('C-wth-result', 'recall', 1, 'Which of the three Transformers is most accurate on WTH after 10 epochs?', 'Informer.', ['Informer'],
 ('4.4.1', 'Informer achieves the best MAE, MSE, and RMSE of the three Transformers on WTH'), TH, 'Table 4.1',
 options=['Informer', 'Autoformer', 'PatchTST', 'They tie'], correct='Informer')
card('C-wth-result', 'recall', 2, 'Recite Table 4.1: parameters, MAE, MSE, RMSE and time for the three Transformers on WTH.', 'Informer 2,901,542 / 0.4802 / 0.4046 / 0.6361 / 1,100.9 s. Autoformer 2,729,766 / 0.5988 / 0.6097 / 0.7808 / 1,252.3 s. PatchTST 399,744 / 0.5084 / 0.4871 / 0.6979 / 1,452.7 s.', ['three rows'],
 [('4.4.1', 'Informer 2,901,542 0.4802 0.4046 0.6361 1,100.9'), ('4.4.1', 'Autoformer 2,729,766 0.5988 0.6097 0.7808 1,252.3'), ('4.4.1', 'PatchTST 399,744 0.5084 0.4871 0.6979 1,452.7')], TH, 'Table 4.1')
card('C-wth-result', 'derivation', 3, 'From Table 4.1, compare PatchTST with Informer on parameters, MSE and time.', 'PatchTST has 7.3x fewer parameters (2,901,542 / 399,744), a 20% higher MSE (0.4871 vs 0.4046) and takes 1.32x longer (1,452.7 vs 1,100.9 s). So on WTH PatchTST is smaller but neither more accurate nor faster.', ['7.3x', '20%', '1.32x'],
 [('4.4.1', 'Informer 2,901,542 0.4802 0.4046 0.6361 1,100.9'), ('4.4.1', 'PatchTST 399,744 0.5084 0.4871 0.6979 1,452.7')], TH, 'Table 4.1')
card('C-wth-result', 'objection', 3, 'Chapter 2 says PatchTST gives "faster training". Table 4.1 says otherwise on WTH. Which do you defend?', 'Defend the table: on WTH PatchTST (1,452.7 s) is slower than Informer (1,100.9 s) and Autoformer (1,252.3 s). The "faster training" claim holds on ETTh1, STEEL and Smart Meters but not WTH, so it must be stated per dataset.', ['uses the table', 'per-dataset statement'],
 [('2.4.5', 'PatchTST achieves improved accuracy, faster training, and lower memory consumption relative to earlier Transformer variants'), ('4.4.1', 'PatchTST 399,744 0.5084 0.4871 0.6979 1,452.7')], TH, 'Table 4.1', note='Register item R-informer-fastest.')

# ---------------- ETTh1 ----------------
concept('C-etth1-result', 'F', 'Result 2: ETTh1 (PatchTST wins)',
 'On ETTh1 PatchTST wins every accuracy metric (MAE 0.4689, MSE 0.3742, RMSE 0.6117) and is the only model that tracks the cyclical oil temperature. Informer collapses to a near-horizontal mean prediction despite the lowest raw training loss.',
 ['4.4.2'], ('4.4.2', 'PatchTST emerges as the definitive winner across every accuracy metric evaluated, achieving an MAE of 0.4689 and MSE of 0.3742'), [TH, N], 0.7, decisionId='D-etth1-percentages')
card('C-etth1-result', 'recall', 1, 'Which Transformer wins every accuracy metric on ETTh1?', 'PatchTST.', ['PatchTST'],
 ('4.4.2', 'PatchTST emerges as the definitive winner across every accuracy metric evaluated'), TH, 'Table 4.2',
 options=['PatchTST', 'Informer', 'Autoformer', 'No clear winner'], correct='PatchTST')
card('C-etth1-result', 'recall', 2, 'Recite Table 4.2 for ETTh1.', 'Informer 2,892,577 / 0.5560 / 0.5652 / 0.7518 / 525.6 s. Autoformer 2,716,961 / 0.5299 / 0.4452 / 0.6673 / 884.5 s. PatchTST 399,744 / 0.4689 / 0.3742 / 0.6117 / 726.4 s.', ['three rows'],
 [('4.4.2', 'Informer 2,892,577 0.5560 0.5652 0.7518 525.6'), ('4.4.2', 'Autoformer 2,716,961 0.5299 0.4452 0.6673 884.5'), ('4.4.2', 'PatchTST 399,744 0.4689 0.3742 0.6117 726.4')], TH, 'Table 4.2')
card('C-etth1-result', 'derivation', 3, 'The thesis says PatchTST improves on Informer by 13.6% (MAE), 25.9% (MSE) and 13.8% (RMSE). Recompute from Table 4.2.', 'Against Informer alone the gains are 15.7% (MAE), 33.8% (MSE), 18.6% (RMSE). The 13.6 / 25.9 / 13.8% figures are the gains over the mean of Informer and Autoformer. Against Autoformer alone: 11.5 / 15.9 / 8.3%. State the baseline, and cite run three_models_comparison_ett_20260903_180948.', ['15.7 / 33.8 / 18.6', 'explains where 13.6 / 25.9 / 13.8 come from', 'names the baseline'],
 [('4.4.2', 'a 13.6% improvement in MAE and a 25.9% improvement in MSE over Informer'), ('4.4.2', 'Informer 2,892,577 0.5560 0.5652 0.7518 525.6'), ('4.4.2', 'PatchTST 399,744 0.4689 0.3742 0.6117 726.4')], TH, 'Table 4.2', decisionId='D-etth1-percentages')
card('C-etth1-result', 'recall', 3, 'What is "mean collapse" and how did Informer show it on ETTh1?', 'Near-horizontal predictions that hug the average, giving a low training loss but no useful signal. Informer showed this on ETTh1 despite the lowest raw training loss of the three models.', ['definition', 'Informer example'],
 ('4.4.2', 'Informer, by contrast, exhibited a pronounced mean-collapse pattern, producing near-horizontal predictions despite achieving the lowest raw training loss of the three models'), TH, '§4.4.2')
card('C-etth1-result', 'figure', 3, 'Figure 4.10 shows ETTh1 oil-temperature predictions. What should you point out for each model?', 'PatchTST closely tracks the cyclical fluctuations of the ground truth in all three windows. Informer is near-horizontal (mean collapse). Autoformer is volatile and drifts away from the ground truth toward the end of the 24-step horizon.', ['three models', 'drift for Autoformer'],
 ('4.4.2', 'PatchTST closely tracked the cyclical fluctuations of the ground truth across all three sampled windows'), TH, '§4.4.2', figure='Figure 4.10')
card('C-etth1-result', 'objection', 3, 'You say your result is within about 2% of the original Informer paper. What is the caveat?', 'The thesis discloses that the task configuration and the 33-feature engineered input differ from the original publications\' native settings (7 features), so the agreement is external validation of the pipeline, not a like-for-like replication. The thesis does not say which published figure was used.', ['validation claim', 'feature-set caveat'],
 ('5.1', "found this study's result within approximately 2% of the published figure"), TH, '§5.1')

# ---------------- STEEL ----------------
concept('C-steel-result', 'F', 'Result 3: STEEL (two Transformers diverge)',
 'On STEEL, Informer and Autoformer produced NaN losses from epoch 1 and never recovered. All four recurrent baselines and PatchTST trained normally. PatchTST had the lowest MSE and RMSE of the seven models; GRU was narrowly best on MAE. Only Informer and Autoformer failed: PatchTST did not.',
 ['4.4.3'], ('4.4.3', 'Informer and Autoformer collapsed to NaN losses from epoch 1 and never recovered'), [TH], 0.95, decisionId='D-seeds-runs')
card('C-steel-result', 'recall', 1, 'Which models diverged to NaN on STEEL?', 'Informer and Autoformer only. PatchTST and all four recurrent models trained stably.', ['exactly two', 'PatchTST survived'],
 ('4.4.3', 'Informer and Autoformer collapsed to NaN losses from epoch 1 and never recovered'), TH, 'Table 4.3',
 options=['Informer and Autoformer', 'All three Transformers', 'PatchTST only', 'All recurrent models'], correct='Informer and Autoformer')
card('C-steel-result', 'recall', 2, 'Recite Table 4.3 (parameters, MAE, MSE, RMSE, time, outcome).', 'LSTM 8,632 / 0.0827 / 0.0419 / 0.2047 / 38.3 s. BiLSTM 18,185 / 0.0746 / 0.0358 / 0.1893 / 48.7 s. GRU 7,320 / 0.0709 / 0.0384 / 0.1960 / 38.4 s. LSTM-16 4,456 / 0.0718 / 0.0420 / 0.2049 / 34.2 s. Informer 87,623 / NaN / 502.0 s (failed ep. 1). Autoformer 88,327 / NaN / 662.7 s (failed ep. 1). PatchTST 34,368 / 0.0766 / 0.0100 / 0.1000 / 173.7 s.', ['seven rows', 'two failures'],
 [('4.4.3', 'LSTM 8,632 0.0827 0.0419 0.2047 38.3 Success'), ('4.4.3', 'GRU 7,320 0.0709 0.0384 0.1960 38.4 Success'), ('4.4.3', 'Informer 87,623 NaN NaN NaN 502.0 Failed (ep. 1)'), ('4.4.3', 'PatchTST 34,368 0.0766 0.0100 0.1000 173.7 Success')], TH, 'Table 4.3')
card('C-steel-result', 'recall', 2, 'Which model was best on STEEL, and on which metric?', 'PatchTST had the lowest MSE and RMSE (0.0100, 0.1000), roughly half of the best recurrent model\'s RMSE; GRU was narrowly ahead on MAE (0.0709).', ['PatchTST on MSE/RMSE', 'GRU on MAE'],
 ('4.4.3', 'PatchTST achieved the lowest MSE and RMSE overall (0.0100, 0.1000)'), TH, 'Table 4.3')
card('C-steel-result', 'register', 3, 'Two STEEL runs give PatchTST different errors (MAE 0.3407 first, 0.0766 second). What explains the drop?', 'Open: the thesis does not explain it. The second run used comparably small capacities (4,456 to 88,327 parameters; PatchTST 34,368) and all seven models; the first run\'s PatchTST configuration is not stated, and the author has not yet said why the error fell about 4.4x in MAE and 30x in MSE. Do not present the two runs as comparable until this is answered.', ['spots the discrepancy', 'does not invent an explanation'],
 [('4.4.3', 'achieving MAE 0.3407, MSE 0.2985, and RMSE 0.5464'), ('4.4.3', 'PatchTST 34,368 0.0766 0.0100 0.1000 173.7 Success')], TH, 'Table 4.3',
 open={'decisionId': None, 'reason': 'The author has not explained why PatchTST error fell between the first and second STEEL run (register item R-steel-two-runs).'})
card('C-steel-result', 'register', 3, 'What does "failed" mean for Informer and Autoformer on STEEL, and how should it be reported?', 'Their training and validation losses became NaN in epoch 1 and metrics are NaN with infinite validation loss. Report them as diverged/failed, not as results. How many epochs actually ran is unresolved: the thesis says NaN persisted for all ten epochs attempted while early stopping (patience 7) would have ended the run earlier.', ['diverged, not a score', 'epochs unresolved'],
 ('4.4.3', 'remaining so for all ten epochs attempted'), TH, '§4.4.3', decisionId='D-seeds-runs',
 open={'decisionId': 'D-seeds-runs', 'reason': 'Epochs actually run on the failed STEEL runs are unresolved (register item R-epochs).'})

concept('C-steel-not-capacity', 'F', 'STEEL: it is not model capacity',
 'The second run gave every architecture a comparably small capacity (4,456 to 88,327 parameters). The smallest model (LSTM-16, 4,456) succeeds and a larger one (Informer, 87,623) fails, so raw capacity cannot explain the collapse.',
 ['4.4.3'], ('4.4.3', 'raw model capacity cannot be the explanation for the collapse'), [TH], 0.8)
card('C-steel-not-capacity', 'recall', 2, 'How does the two-run design rule out model size?', 'The second run set all seven models to comparably small capacity. LSTM-16 with 4,456 parameters trains fine while Informer with 87,623 fails, so size cannot be the cause. The failing models are also smaller than the 399,744-parameter PatchTST used successfully on WTH and ETTh1.', ['small models fail', 'smallest succeeds'],
 ('4.4.3', 'the smallest-capacity model in the entire comparison (LSTM-16, at 4,456 parameters) succeeds'), TH, 'Table 4.3')
card('C-steel-not-capacity', 'derivation', 3, 'How many times larger are the failing Transformers than the successful recurrent models? The thesis says "two to ten times".', 'From Table 4.3 the ratios run from 4.8x (Informer 87,623 / BiLSTM 18,185) to 19.8x (Autoformer 88,327 / LSTM-16 4,456), with 10.2x against LSTM. "Two to ten times" understates it; the argument only gets stronger.', ['ratios computed', 'spots the understatement'],
 [('4.4.3', 'only two to ten times larger than the successful recurrent models'), ('4.4.3', 'LSTM-16 4,456 0.0718 0.0420 0.2049 34.2 Success')], TH, 'Table 4.3', note='Register item R-derived-ratios.')

concept('C-steel-not-mixing', 'F', 'STEEL: it is not channel-mixing in general',
 'Every recurrent model feeds all seven STEEL variables jointly into one input vector at each timestep, and none of them fail. So mixing channels is not by itself the cause.',
 ['4.4.3'], ('4.4.3', 'every recurrent model processes all seven STEEL variables jointly'), [TH], 0.8)
card('C-steel-not-mixing', 'recall', 3, 'Why can the failure not be attributed to channel-mixing in general?', 'Every recurrent model processes all seven STEEL variables jointly, concatenated into a single input vector per timestep, and none fail. The discriminating property is whether mixing happens through an unbounded cross-channel attention or correlation computation.', ['RNNs mix channels and succeed', 'unbounded attention is the difference'],
 ('4.4.3', 'because every recurrent model processes all seven STEEL variables jointly, concatenated into a single input vector at each timestep, and none of them fail'), TH, '§4.4.3')

concept('C-steel-mechanism', 'F', 'STEEL mechanism: bounded versus unbounded',
 'Recurrent gates are sigmoid-bounded and their updates tanh-bounded, so any single input has a bounded effect. Self-attention and auto-correlation compute raw scores with no bound, so a heavy-tailed value that survives standardisation in one channel can dominate a computation that mixes all channels. PatchTST keeps attention within each channel, so an outlier in one channel cannot inflate attention for another. The thesis treats this as a hypothesis.',
 ['4.4.3', '4.6.2', '1.5'], ('4.4.3', 'The evidence instead points to a specific, previously under-specified mechanism: a bounded-activation explanation'), [TH, 'wortsman2023instabilities', 'dehghani2023vit22b'], 1.0)
card('C-steel-mechanism', 'recall', 1, 'What property separates the two failing STEEL models from the five that train?', 'Whether channel mixing happens through an unbounded, cross-channel attention or correlation computation (Informer, Autoformer) or is bounded (recurrent gates) or within-channel (PatchTST).', ['unbounded cross-channel', 'bounded or within-channel'],
 ('4.4.3', 'but specifically whether that mixing occurs through an unbounded, cross-channel attention or correlation computation'), TH, '§4.4.3',
 options=['Unbounded cross-channel attention or correlation', 'Parameter count', 'Channel mixing in general', 'Softmax exponentiation'], correct='Unbounded cross-channel attention or correlation')
card('C-steel-mechanism', 'recall', 2, 'Give the bounded-activation account of the STEEL failure in your own words.', 'LSTM, BiLSTM, GRU and LSTM-16 use sigmoid gates and tanh updates, so any one input\'s contribution is bounded. Self-attention and auto-correlation compute raw dot-product or correlation scores with no bound. A heavy-tailed value that survives Z-score standardisation can then dominate the mixed computation, producing exploding values consistent with NaN propagation. PatchTST computes attention only within each channel\'s patches, so an outlier cannot affect other channels.', ['bounded gates', 'unbounded scores', 'PatchTST within-channel'],
 [('4.4.3', 'Self-attention and auto-correlation, by contrast, compute raw dot-product or correlation scores with no such bound'), ('4.4.3', 'an outlier value in one channel cannot inflate the attention computation carried out for a different channel')], TH, '§4.4.3')
card('C-steel-mechanism', 'objection', 3, 'StandardScaler already gives every column unit variance. How can a 10⁻¹ to 10⁶ scale gap cause NaN?', 'The objection is fair: after fitting, columns have equal variance, so a cross-feature scale gap is not what reaches attention. The thesis argues that a heavy-tailed value can survive standardisation in one channel and dominate an unbounded mixing computation, and it says standardisation alone did not prevent instability. It presents this as a hypothesis supported by the evidence, and confirmation (logging attention-logit magnitudes) is future work. Other candidates the diagnostics would separate: bad or constant columns, test values outside the training range, precision limits and gradient explosion.', ['concedes the objection', 'heavy tails survive scaling', 'calls it a hypothesis', 'names the diagnostic'],
 [('4.4.3', 'A heavy-tailed value that survives Z-score standardisation in one channel'), ('1.5', 'this thesis treats that mechanism as a hypothesis supported by the available evidence rather than a definitively established causal finding')], TH, '§4.4.3', note='Design doc section 5. The extra candidates come from the design doc, not the thesis.')
card('C-steel-mechanism', 'objection', 3, 'Section 4.6.2 says the evidence "isolates the specific property". Section 1.5 says the mechanism is a hypothesis. Which is it?', 'Both must be reconciled: the two-run evidence rules out capacity and channel mixing in general and singles out unbounded cross-channel computation, but no ablation or logging has confirmed the mechanism (5.2 lists it as future work). Say "best-supported hypothesis", and soften 4.6.2 or 5.1 wording.', ['evidence vs proof', 'names the wording conflict'],
 [('4.6.2', 'The evidence instead isolates the specific property shared by the two failing architectures'), ('1.5', 'pending confirmatory ablation experiments identified as future work')], TH, '§4.6.2', note='Register item R-mechanism-claim.')
card('C-steel-mechanism', 'transfer', 4, 'PatchTST normalises each window with RevIN and machines on STEEL can sit near-constant. Why did PatchTST not blow up?', 'The thesis does not test this. Its explanation is structural: attention is computed within each channel, so an outlier cannot spread. A near-constant window could in principle push an instance standard deviation towards zero, so a stated reason would need a diagnostic (check window standard deviations and NaNs in the input tensor). Present it as a hypothesis you can test.', ['structural explanation', 'admits no test', 'proposes a check'],
 ('3.2.3', 'energy usage ranges from 0 to 157.18 kWh'), N, 'Patching and channel independence', note='Extension beyond the thesis (design doc section 5, objection 3).')

concept('C-steel-superseded', 'F', 'The superseded softmax-overflow account',
 'An earlier stage of the research blamed softmax exponentiation exceeding the floating-point range. The final thesis supersedes that: modern attention subtracts the row-wise maximum from the logits before exponentiating, so direct softmax overflow is an unlikely primary cause on its own.',
 ['4.4.3'], ('4.4.3', 'This refined mechanism directly supersedes an earlier, less precise account', 'exceeding the floating-point representable range'), [TH, 'micikevicius2018mixed'], 0.9)
card('C-steel-superseded', 'recall', 2, 'What did the earlier account of the STEEL failure say, and why was it dropped?', 'It attributed the failure to softmax exponentiation exceeding the floating-point range. It was dropped because modern attention implementations subtract the row-wise maximum from the logits before exponentiating, which prevents this failure, so direct softmax overflow is an unlikely primary cause on its own.', ['old account', 'row-max subtraction'],
 [('4.4.3', 'This refined mechanism directly supersedes an earlier, less precise account', 'exceeding the floating-point representable range'), ('4.4.3', 'modern attention implementations subtract the row-wise maximum from attention logits before exponentiation')], 'micikevicius2018mixed', 'FP16 range', note='Micikevicius et al. is the thesis reference [44] for the overflow phenomenon (design doc status: verify).')
card('C-steel-superseded', 'objection', 3, 'If softmax is protected, where could a NaN come from instead?', 'Upstream of the softmax: attention logits growing without bound during training, exploding gradients at the learning rate, reduced-precision overflow, or NaNs already present in the scaled input. The thesis names unbounded raw scores as its explanation and leaves confirmation to future logging; the other causes are why a diagnostic plan matters.', ['upstream causes', 'links to diagnostics'],
 ('4.4.3', 'making a direct softmax overflow an unlikely primary cause on its own'), 'wortsman2023instabilities', 'Attention logit growth', note='Beyond the thesis: attention-logit growth is documented by Wortsman et al. and Dehghani et al. (both on the design doc\'s verify list, not in the thesis references).')

concept('C-steel-diagnostics', 'F', 'How you would confirm the STEEL mechanism',
 'The thesis lists confirmatory diagnostics as future work: instrument attention-logit magnitudes during early STEEL training and try robust, outlier-resistant scaling for Informer and Autoformer. A crisp diagnostic plan earns more respect than a confident mechanism.',
 ['5.2'], ('5.2', 'directly instrument attention-logit magnitudes during early STEEL training to empirically confirm the bounded-activation mechanism'), [TH, 'wortsman2023instabilities', 'micikevicius2018mixed'], 0.9)
card('C-steel-diagnostics', 'recall', 2, 'What confirmatory diagnostics does the thesis propose for STEEL?', 'Instrument attention-logit magnitudes during early STEEL training to confirm the bounded-activation mechanism, evaluate robust outlier-resistant scaling for Informer/Autoformer, and complete the recurrent-baseline comparison on WTH and ETTh1.', ['logit logging', 'robust scaling', 'missing RNN runs'],
 ('5.2', 'directly instrument attention-logit magnitudes during early STEEL training to empirically confirm the bounded-activation mechanism'), TH, '§5.2')
card('C-steel-diagnostics', 'transfer', 4, 'You still have the code. List the runs that would turn the STEEL claim from a hypothesis into evidence, and what each would tell you.', 'Assert no NaN or inf after scaling and count zero-variance columns (bad input). Log the maximum attention logit and gradient norm for the first 50 steps (logit growth or gradient explosion). Rerun in float32 only with gradient clipping and a lower learning rate (precision or instability). Try RobustScaler or log1p on heavy-tailed columns and drop constant columns (heavy tails). Use anomaly detection to find the first NaN-producing operation. The first two are in the thesis\'s future work; the rest extend it.', ['input checks', 'logit and gradient logging', 'precision and clipping rerun', 'robust scaling'],
 ('5.2', 'evaluate robust, outlier-resistant scaling'), 'micikevicius2018mixed', 'Loss scaling', note='Design doc section 5 list; only logit instrumentation and robust scaling appear in the thesis (5.2).')

# ---------------- Smart Meters ----------------
concept('C-smart-meters-result', 'F', 'Result 4: Smart Meters (PatchTST wins everything)',
 'On the largest, 26-feature dataset PatchTST wins MAE, MSE and RMSE outright (2.5819 / 20.1874 / 4.4930) with the fewest parameters (9,120). It trains in about a third of the Transformer time but 2 to 3 times slower than the recurrent models. LSTM-16 is fastest but least accurate. All models were capped at 3 epochs.',
 ['4.5'], ('4.5', 'PatchTST decisively outperformed all six other models'), [TH], 0.7, decisionId='D-london-data')
card('C-smart-meters-result', 'recall', 1, 'Which model is most accurate on Smart Meters?', 'PatchTST (MAE 2.5819, MSE 20.1874, RMSE 4.4930).', ['PatchTST'],
 ('4.5', 'PatchTST decisively outperformed all six other models'), TH, 'Table 4.4',
 options=['PatchTST', 'Autoformer', 'GRU', 'LSTM-16'], correct='PatchTST')
card('C-smart-meters-result', 'recall', 2, 'Recite Table 4.4.', 'LSTM 18,816 / 5.2733 / 81.4314 / 9.0239 / 1,279.4. BiLSTM 38,097 / 7.1175 / 98.8821 / 9.9439 / 1,592.2. GRU 16,896 / 5.2432 / 75.3838 / 8.6824 / 1,283.3. LSTM-16 13,424 / 8.5613 / 110.1040 / 10.4930 / 1,189.7. Informer 27,610 / 6.0268 / 99.1785 / 9.9588 / 11,119.1. Autoformer 29,786 / 4.2817 / 38.6661 / 6.2182 / 10,694.7. PatchTST 9,120 / 2.5819 / 20.1874 / 4.4930 / 3,905.5.', ['seven rows'],
 [('4.5', 'GRU 16,896 5.2432 75.3838 8.6824 1,283.3'), ('4.5', 'Autoformer 29,786 4.2817 38.6661 6.2182 10,694.7'), ('4.5', 'PatchTST 9,120 2.5819 20.1874 4.4930 3,905.5')], TH, 'Table 4.4')
card('C-smart-meters-result', 'derivation', 3, 'Reproduce the 57.6%, 76.0% and 50.4% improvements of PatchTST over the other six models.', 'Mean of the other six: MAE 6.0840, MSE 83.941, RMSE 9.0534. PatchTST: 2.5819, 20.1874, 4.4930. Improvements: (6.0840-2.5819)/6.0840 = 57.6%, (83.941-20.1874)/83.941 = 76.0% (75.95), (9.0534-4.4930)/9.0534 = 50.4%. These reproduce from the table.', ['mean of six', 'three percentages'],
 ('4.5', 'improving on the average of the other six models by 57.6%, 76.0%, and 50.4%'), TH, 'Table 4.4')
card('C-smart-meters-result', 'derivation', 3, 'Compare PatchTST\'s training time with the other Transformers and with the recurrent models.', 'PatchTST 3,905.5 s is about 35 to 37% of Informer/Autoformer (11,119.1 / 10,694.7 s), so roughly a third. Against the recurrent models (1,189.7 to 1,592.2 s) it is about 2.5 to 3.3 times slower, matching "two to three times slower".', ['about a third', '2.5-3.3x'],
 [('4.5', 'trained in roughly a third of the time of Informer or Autoformer (3,905.5s vs. 10,694.7'), ('4.5', 'it remained two to three times slower than any recurrent model')], TH, 'Table 4.4')
card('C-smart-meters-result', 'recall', 3, 'Why can the Smart Meters comparison not be run to convergence, and what does that imply?', 'All seven models were capped at 3 completed epochs because Transformer epochs are long, so results are a fixed-budget comparison, not early-stopping convergence. The author\'s script comment says the cap was "reduced epochs for faster testing"; the thesis attributes it to run time. Disclose it as a boundary condition.', ['3-epoch cap', 'disclosed boundary'],
 ('4.5', 'all seven models were capped at 3 completed epochs rather than run to full early-stopping convergence'), TH, '§4.5', decisionId='D-seeds-runs')
card('C-smart-meters-result', 'objection', 3, 'Informer and Autoformer trained fine on London. Is that consistent with your bounded-activation account of STEEL?', 'Yes, as a hypothesis: the thesis reports that standardisation was sufficient for Smart Meters and describes extreme scale heterogeneity (six to seven orders of magnitude) only for STEEL, so the account predicts no collapse there. Informer\'s weaker accuracy there (MAE 6.0268) is a separate matter. It does not prove the mechanism, and confirmation needs the diagnostics.', ['consistent as a hypothesis', 'links to scale heterogeneity'],
 ('3.3', 'this standardisation proved sufficient for the WTH, ETTh1, and Smart Meters datasets'), TH, '§3.3')

# ---------------- Synthesis ----------------
concept('C-dataset-conditional', 'F', 'PatchTST\'s advantage is dataset-conditional',
 'PatchTST is the strongest choice on rich, higher-dimensional data (decisively on ETTh1 and Smart Meters). On simpler continuous data (WTH) Informer wins on accuracy. The right summary is not "PatchTST dominates".',
 ['4.6.1'], ('4.6.1', 'PatchTST is the strongest choice on rich, higher-dimensional data where accuracy is the priority'), [TH, N], 0.6)
card('C-dataset-conditional', 'recall', 2, 'State the correct one-sentence summary of PatchTST versus Informer.', 'PatchTST is the strongest choice on rich, higher-dimensional data where accuracy is the priority; Informer remains competitive, and sometimes superior, on simpler continuous data or where training speed among Transformers matters.', ['conditional statement'],
 ('4.6.1', 'PatchTST is the strongest choice on rich, higher-dimensional data where accuracy is the priority', 'training speed among Transformers matters'), TH, '§4.6.1')
card('C-dataset-conditional', 'recall', 2, 'Name the three design choices the thesis credits for PatchTST\'s strength.', 'Temporal patching, channel independence and architectural efficiency (compact structure compared with Autoformer).', ['three choices'],
 ('4.6.1', 'stems from three synergistic design choices'), TH, '§4.6.1')
card('C-dataset-conditional', 'contrast', 3, 'Where does PatchTST win and where does it lose, dataset by dataset?', 'WTH: Informer best on all accuracy metrics. ETTh1: PatchTST best on all. STEEL: PatchTST best MSE/RMSE, GRU best MAE, Informer and Autoformer fail. Smart Meters: PatchTST best on all three metrics.', ['four datasets'],
 [('4.6.1', 'On WTH, Informer achieves better MAE, MSE, and RMSE than PatchTST'), ('4.6.1', 'decisively so on ETTh1 and Smart Meters')], TH, 'Table 4.4')

concept('C-frontier', 'F', 'The accuracy–efficiency Pareto frontier',
 'No single model dominates. PatchTST sits at the accuracy end on feature-rich data and is the most parameter-efficient Transformer everywhere. Informer is faster than the other Transformers on WTH and ETTh1 only. Recurrent models, especially GRU and LSTM-16, sit at the efficiency end.',
 ['4.6.3', '4.5'], ('4.6.3', 'The full four-dataset comparison delineates a genuine Pareto frontier rather than a single dominant model'), [TH], 0.7, decisionId='D-informer-fastest')
card('C-frontier', 'recall', 2, 'Describe the frontier in one line per corner.', 'Accuracy: PatchTST on feature-rich data, while the most parameter-efficient Transformer everywhere. Speed among Transformers: Informer on WTH and ETTh1 (not STEEL or Smart Meters, where PatchTST is faster). Efficiency: the recurrent models, especially GRU and LSTM-16.', ['three corners', 'corrects the Informer claim'],
 ('4.6.3', 'PatchTST defines the accuracy end of that frontier on feature-rich datasets while remaining the most parameter-efficient Transformer everywhere'), TH, 'Table 4.4', decisionId='D-informer-fastest')
card('C-frontier', 'objection', 3, 'The thesis says Informer trains fastest of the Transformers on every dataset. Check that against the tables.', 'It is true on WTH (1,100.9 s vs 1,252.3 and 1,452.7) and ETTh1 (525.6 s vs 884.5 and 726.4). It is false on STEEL (PatchTST 173.7 s vs Informer 502.0 s) and Smart Meters (PatchTST 3,905.5 s vs Informer 11,119.1 s). Restrict the claim to WTH and ETTh1.', ['checks four datasets', 'restricts the claim'],
 [('4.6.1', 'Informer is the fastest of the three Transformers to train on every dataset examined in this chapter'), ('4.4.3', 'PatchTST 34,368 0.0766 0.0100 0.1000 173.7 Success')], TH, 'Table 4.3', decisionId='D-informer-fastest')

concept('C-selection-framework', 'F', 'The hardware- and data-aware model-selection framework',
 'The thesis concludes that no architecture is unconditionally best. PatchTST for accuracy on rich data; Informer for a speed edge among Transformers and on simpler data; recurrent models (especially GRU) where training speed or size dominate; and on industrial data, numerical stability comes first.',
 ['5.1', '4.6.2'], ('5.1', 'This thesis therefore concludes that no single architecture is unconditionally superior for long-term load forecasting'), [TH], 0.6)
card('C-selection-framework', 'recall', 2, 'State the thesis\'s central conclusion and its three recommendations.', 'No single architecture is unconditionally superior. PatchTST for accuracy-critical use on rich, higher-dimensional data; Informer for a speed advantage among Transformers and simpler data; recurrent models, particularly GRU, where training speed or footprint dominate. On industrial data numerical stability comes first.', ['central conclusion', 'three recommendations'],
 ('5.1', 'no single architecture is unconditionally superior for long-term load forecasting'), TH, '§5.1')
card('C-selection-framework', 'transfer', 4, 'A plant has STEEL-like data: extreme scale heterogeneity, machines switching on and off. Which architectures do you allow and why?', 'Prefer bounded-activation recurrence (GRU, LSTM) or channel-independent attention (PatchTST). Avoid Informer and Autoformer unless mitigations are shown, because architectures that compute unbounded attention or correlation jointly across raw channels carry a specific, identifiable numerical risk independent of parameter count.', ['names both viable options', 'excludes the two failing models', 'gives the reason'],
 ('4.6.2', 'either bounded-activation recurrence or channel-independent attention are both viable mitigations'), TH, '§4.6.2')
card('C-selection-framework', 'transfer', 4, 'A small lab has a 6 GB GPU, feature-rich load data and needs the best accuracy. What do you pick and what would you check first?', 'PatchTST: it won ETTh1 and Smart Meters and is the smallest Transformer. Check that training fits your card (the thesis reduced dimensions and batch size to fit 6GB), and remember memory was not measured. If training speed dominates, GRU is the efficient alternative.', ['PatchTST', 'memory caveat', 'GRU alternative'],
 ('5.1', 'PatchTST is strongest for accuracy-critical deployment on rich, higher-dimensional data'), TH, '§5.1', decisionId='D-vram')

concept('C-rqs-gaps', 'F', 'Research questions and gaps',
 'RQ1: Transformers versus recurrent baselines under a fixed hardware budget. RQ2: robustness on industrial data. RQ3: failures and their mechanisms. RQ4: a hardware- and data-aware selection guidance. The four gaps: hardware-aware selection, data-driven suitability, the accuracy–efficiency trade-off, and failure-mode documentation.',
 ['1.3', '2.5'], ('1.3', 'RQ2. To what extent do Transformer-based models demonstrate robustness and generalization when applied to industrial energy consumption data'), [TH, 'wen2023survey'], 0.5)
card('C-rqs-gaps', 'recall', 2, 'State the four research questions.', 'RQ1: Transformers vs recurrent baselines under a fixed hardware budget. RQ2: robustness and generalisation on industrial data. RQ3: data characteristics and mechanisms behind failures. RQ4: practical hardware- and data-aware guidance.', ['four RQs'],
 ('1.3', 'RQ4. Can the findings from these comparisons be synthesized into practical, hardware- and data-aware guidance'), TH, '§1.3')
card('C-rqs-gaps', 'recall', 2, 'Name the four research gaps from the literature review.', 'Hardware-aware model selection; data-driven model suitability; accuracy–efficiency trade-offs; failure-mode documentation.', ['four gaps'],
 ('2.5', 'Hardware-Aware Model Selection'), TH, '§2.5')
card('C-rqs-gaps', 'recall', 1, 'Which gap says failures are "rarely documented with sufficient diagnostic detail"?', 'Failure-mode documentation.', ['failure-mode documentation'],
 ('2.5', 'are rarely documented with sufficient diagnostic detail to support practical risk assessment'), 'wen2023survey', 'Taxonomy',
 options=['Failure-mode documentation', 'Hardware-aware model selection', 'Data-driven model suitability', 'Accuracy-efficiency trade-offs'], correct='Failure-mode documentation')

concept('C-limitations', 'F', 'Limitations and future work',
 'Scope: energy data only, seven models, four public datasets, one 6GB GPU, fixed hyperparameters, and a failure mechanism treated as a hypothesis. Future work: confirmatory diagnostics, edge deployment (pruning, quantisation, distillation), interpretability, other domains, hybrid and federated models, probabilistic and continual forecasting.',
 ['1.5', '5.2'], ('1.5', 'this study exclusively addresses energy consumption data as its use case'), [TH, 'hinton2015distill', 'han2016compression', 'jacob2018quant', 'mcmahan2017fedavg', 'serrano2019attention', 'lopezpaz2017gem'], 0.5)
card('C-limitations', 'recall', 2, 'List the stated limitations in the scope section.', 'Energy data only; the chosen models and baselines bound the comparison; hyperparameters held fixed (may understate best-case performance); the failure mechanism is a hypothesis pending ablations; public datasets constrain quality and documentation.', ['five limitations'],
 ('1.5', 'reliance on publicly available datasets means the study is constrained by their characteristics, quality, and documentation'), TH, '§1.5')
card('C-limitations', 'recall', 2, 'Which techniques does the thesis propose for edge deployment?', 'Structured pruning, quantisation and knowledge distillation (plus the TinyML literature).', ['pruning', 'quantisation', 'distillation'],
 ('5.2', 'evaluate structured pruning, quantization [46, 56], and knowledge distillation [45]'), 'han2016compression', 'Pruning', note='The thesis cites the TinyML literature as [61], which does not match the reference list (register item R-citations).')
card('C-limitations', 'recall', 1, 'Which future direction addresses "genuinely individual household-level smart-meter data"?', 'Federated learning.', ['federated learning'],
 ('5.2', 'federated learning approaches [55] for genuinely individual'), 'mcmahan2017fedavg', 'FederatedAveraging',
 options=['Federated learning', 'Knowledge distillation', 'Quantisation', 'Anomaly detection'], correct='Federated learning')
card('C-limitations', 'recall', 2, 'Which other domains does the thesis name for the framework, and which references?', 'Traffic forecasting [52] (DCRNN), financial forecasting [53] (DeepLOB) and time-series anomaly detection [54] (Anomaly Transformer).', ['three domains'],
 ('5.2', 'traffic forecasting [52], financial forecasting [53]'), 'li2018dcrnn', 'Traffic forecasting')

concept('C-motivation', 'F', 'Why long-term load forecasting, and the gap',
 'Global electricity demand is growing and grids must integrate variable renewables, so accurate long-term load forecasting supports grid stability and planning. Transformers promise long-range modelling but cost O(L²), and benchmark evidence is rarely gathered under realistic hardware limits or on industrial data. That gap is the thesis\'s central motivation.',
 ['1.1', '1.1.1'], ('1.1', 'This gap between idealized benchmark evaluation and practical deployment realities constitutes the central motivation of this research'), [TH, 'vaswani2017', 'lheureux2022energies', 'zeng2023dlinear'], 0.2)
card('C-motivation', 'recall', 1, 'What is the central motivation of the research?', 'The gap between idealised benchmark evaluation and practical deployment realities (memory and compute limits, industrial data).', ['benchmark vs deployment gap'],
 ('1.1', 'This gap between idealized benchmark evaluation and practical deployment realities constitutes the central motivation of this research'), TH, '§1.1',
 options=['Benchmarks versus deployment realities', 'Replacing recurrent models entirely', 'Proving PatchTST is best', 'Reducing dataset size'], correct='Benchmarks versus deployment realities')
card('C-motivation', 'recall', 2, 'Why does precise long-term load forecasting matter?', 'It supports grid stability, efficient resource allocation and the integration of variable renewable generation, and is central to the energy transition.', ['grid stability', 'renewables'],
 ('1.1', 'Precise long-term load forecasting has consequently become central not only to operational efficiency but to the broader energy transition'), 'lheureux2022energies', 'Transformer for load forecasting')
card('C-motivation', 'recall', 2, 'What benefits of accurate, efficient load forecasting does the significance section list?', 'Optimised generation planning and scheduling, demand-response support, stable integration of renewables, lower waste and costs, more reliable service, and sustainability.', ['at least four benefits'],
 ('1.1.1', 'It supports demand-response strategies by helping organizations anticipate periods of high or low electricity consumption'), TH, '§1.1.1')
